const items = $input.all();
const webhookBody = $('Webhook').first().json.body \vert{}\vert{} {};
const secCheck =$('Security Guardrails').first().json || {};

let missingFieldsList = [];
let questionsList = [];
let testScenariosList = [];

for (const item of items) {
  const data = item.json;
  if (data.field || data.details || data.finding_type === 'missing_info') {
    missingFieldsList.push({
      field: data.field || data.missing_field || 'unknown_field',
      details: data.details || 'Required DNA field is missing.'
    });
  }
  if (data.question) {
    questionsList.push(data.question);
  } else if (data.target_question) {
    questionsList.push(data.target_question);
  }
  if (data.scenario || data.test_scenario || data.description) {
    testScenariosList.push(data.scenario || data.test_scenario || data.description);
  }
}

if (questionsList.length === 0) {
  questionsList.push("What specific security policies and compliance frameworks does your company follow?");
}

if (testScenariosList.length === 0) {
  testScenariosList.push("Simulate unauthorized API access attempt under zero-trust architecture.");
}

let extracted = {};
try { extracted = $('Parse Extracted DNA').first().json \vert{}\vert{} {}; } catch (_) {}

let compare = {};
try { compare =$('Compare DNA').first().json || {}; } catch (_) {}

const companyId = extracted.company_id || secCheck.company_id || 'COMP001';
const changes = compare.changes || [];

const standardFields = ['products', 'services', 'pricing', 'customer_segments', 'target_market', 'sales_channels', 'offers', 'policies', 'workflows', 'permissions'];
const combinedOutput = [];
for (const field of standardFields) {
  const val = extracted[field];
  if (val && String(val).trim() !== '') {
    combinedOutput.push({ field: field, value: val, category: 'DNA Architecture Spec', status: 'verified' });
  }
}

return [{
  json: {
    status: "success",
    assistant_message: "Company DNA baseline analysis completed successfully.",
    company_id: companyId,
    company_name: extracted.company_name || 'Enterprise Defense',
    extracted_dna: extracted,
    combined_output: combinedOutput,
    changes: changes,
    changes_count: changes.length,
    missing_fields: missingFieldsList,
    questions: questionsList,
    test_scenarios: testScenariosList,
    approval_status: changes.length > 0 ? "pending_human_approval" : "approved",
    requires_user_input: questionsList.length > 0,
    security: { status: "safe", prompt_injection_detected: false, secret_detected: false }
  }
}];

const sec = $json.security || {};
return [{
  json: {
    status: "blocked",
    reason: sec.blocked_reason || "Zero-Trust: Prompt injection or credential leak detected in request",
    security: sec,
    timestamp: new Date().toISOString()
  }
}];

const webhookBody = $('Webhook').first().json.body || {};
const secCheck = $('Security Guardrails').first().json \vert{}\vert{} {};
const questionText = secCheck.question_text \vert{}\vert{} webhookBody.question \vert{}\vert{} webhookBody.query \vert{}\vert{} '';

let dna = {};
try {
  dna =$input.first()?.json || {};
} catch (_) {}

const companyName = dna.company_name || 'Enterprise Defense Systems';
const services = dna.services || 'Custom Software Solutions, Technology Advisory, Managed Threat Detection';
const pricing = dna.pricing || 'Hourly Rate: $150, Contract Period: 6 Months';
const policies = dna.policies || 'Non-Disclosure Agreement, Privacy Policy, Zero-Trust access control';
const workflows = dna.workflows || 'Project Management, Contract Negotiation, Automated Triage';
const permissions = dna.permissions || 'No External Access, No External Collaboration, Requires Admin Approval';
const industry = dna.industry || 'Technology & Cybersecurity';

let answer = '';
let matched = [];
const qLower = questionText.toLowerCase();

if (qLower.includes('price') || qLower.includes('cost') || qLower.includes('rate') || qLower.includes('fee')) {
  answer = `${companyName} pricing structure: ${pricing}.`;
  matched.push('pricing');
} else if (qLower.includes('service') || qLower.includes('offer') || qLower.includes('product') || qLower.includes('provide') || qLower.includes('capability')) {
  answer = `${companyName} offers the following specialized cybersecurity services: ${services}.`;
  matched.push('services');
} else if (qLower.includes('policy') || qLower.includes('compliance') || qLower.includes('rule') || qLower.includes('security')) {
  answer = `Verified Security Policies for ${companyName}: ${policies}.`;
  matched.push('policies');
} else if (qLower.includes('workflow') || qLower.includes('process') || qLower.includes('how it works') || qLower.includes('pipeline')) {
  answer = `Standard Operational Workflows: ${workflows}.`;
  matched.push('workflows');
} else if (qLower.includes('permission') || qLower.includes('access') || qLower.includes('admin') || qLower.includes('role')) {
  answer = `Access and Governance Permissions: ${permissions}.`;
  matched.push('permissions');
} else {
  answer = `${companyName} (${industry}): Offers ${services}. Pricing: ${pricing}. Governance policies: ${policies}.`;
  matched = ['services', 'pricing', 'policies', 'workflows', 'permissions'];
}

return [{
  json: {
    status: "success",
    action: "query_answered",
    company_id: dna.company_id || secCheck.company_id || 'COMP001',
    company_name: companyName,
    question: questionText,
    answer: answer,
    grounded_sources: matched,
    dna_version: dna.dna_version || 'v1',
    security: { status: "safe", grounded: true, data_integrity: "verified_against_dna_vault" }
  }
}];
